from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent
index=json.loads((ROOT/'scene-index.json').read_text())
cards = []
for entry in index:
    folder, title = entry['folder'], entry['title']
    newest = entry['studies'][0] if entry['studies'] else {'label': 'r2 分镜', 'path': entry['storyboard'][0]}
    links = ''.join(f'<a href="{escape(p)}" target="_blank">镜头 {Path(p).stem[:2]} 原图 ↗</a>' for p in entry['storyboard'])
    links += ''.join(f'<a href="{escape(v["path"])}" target="_blank">{escape(v["label"])} ↗</a>' for v in entry['studies'])
    cards.append(f'<article id="{folder}"><div class="scene-title"><span>{folder[:2]}</span><h2>{title}</h2></div><a href="{escape(newest["path"])}" target="_blank"><img loading="lazy" src="{escape(newest["path"])}" alt="{title} · {escape(newest["label"])}"></a><p class="status">{escape(newest["label"])}</p><div class="links">{links}</div><p class="path">scenes/{folder}/</p></article>')

html = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PISCO — 官网内容与场景素材</title><style>
@font-face{font-family:Inria;src:url('brand/inria-serif-400.ttf');font-weight:400}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#080808;color:#e5dfba;font:15px/1.7 Inria,Georgia,serif}main,header,footer{width:min(1160px,90%);margin:auto}header{display:flex;align-items:center;justify-content:space-between;padding:30px 0;border-bottom:1px solid #e5dfba30}.logo{width:140px}a{color:inherit;text-underline-offset:5px}.intro{padding:60px 0 35px}.eyebrow{letter-spacing:.18em;font-size:12px;color:#e5dfba99}h1{font-size:clamp(34px,6vw,68px);font-weight:400;line-height:1.1;margin:20px 0}h2{font-size:29px;font-weight:400;margin:0}.lead{max-width:760px;color:#e5dfbac9}.actions,.links{display:flex;gap:15px 25px;flex-wrap:wrap}.actions{margin-top:26px}.actions a{padding:12px 20px;border:1px solid #e5dfba66;text-decoration:none}.actions a:first-child{background:#e5dfba;color:#000}nav{display:flex;gap:14px 25px;flex-wrap:wrap;padding:24px 0;border-block:1px solid #e5dfba30}article{padding:48px 0;border-bottom:1px solid #e5dfba30}.scene-title{display:flex;align-items:center;gap:20px;margin-bottom:20px}.scene-title span,.path{color:#e5dfba80;font-size:12px}article img{display:block;width:100%;height:auto;background:#161616}article .status{margin:12px 0;color:#e5dfbac9;font-size:13px}.links{font-size:13px}.path{font-family:monospace}.callout{border-left:2px solid #e5dfba70;padding-left:20px;margin-top:28px}footer{padding:40px 0;color:#e5dfba99;font-size:13px}@media(max-width:600px){header{font-size:11px}.logo{width:105px}.intro{padding-top:36px}h1{line-height:1.25}h2{font-size:25px}.actions{flex-direction:column}.actions a{text-align:center}article{padding:32px 0}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><header><img class="logo" src="brand/pisco-logo-latest.svg" alt="PISCO"><span>2026.11.13 / 内容与素材整理</span></header><main><section class="intro"><p class="eyebrow">BEHIND THE CURTAIN / WORK IN PROGRESS</p><h1>从一场相遇，<br>进入另一个故事。</h1><p class="lead">六个世界的人物静态图已全部按新参考重做：服装、姿态、构图与光线统一为更有张力的电影摄影方向。14 张 r2 分镜、6 张最新图与 6 张旧版风格图，按场景分别归档。</p><div class="actions"><a href="website/art-study.html#private-club">查看六幕新图在官网中的效果 ↗</a><a href="website/index.html">查看六幕文案与现有视频 ↗</a></div><p class="callout">六幕新图均为静态风格提案，官网预览保留滚动、撕裂与环境光影。相邻转场分镜仍保留旧版参考，人物视频尚未重新生成。</p></section><nav>NAV</nav>CARDS</main><footer>原始六句对白保留。最新原始 Logo · Inria Serif Regular 400。<br><a href="PC-HANDOFF.txt">PC 接续说明</a> · <a href="scene-index.json">场景文件索引</a> · <a href="assets-manifest.json">文件校验清单</a></footer></body></html>'''
nav = ''.join(f'<a href="#{e["folder"]}">{e["title"]}</a>' for e in index)
(ROOT / 'review.html').write_text(html.replace('NAV', nav).replace('CARDS', ''.join(cards)))
